package ocean;
import ocean.database.DatabaseConnection;import ocean.service.*;import ocean.ui.UserInterface;import javax.swing.*;
public class Main {public static void main(String[] args){try{DatabaseConnection.initialize();}catch(Exception e){JOptionPane.showMessageDialog(null,"Could not initialize the local ocean database:\n"+e.getMessage(),"Startup error",JOptionPane.ERROR_MESSAGE);return;}SwingUtilities.invokeLater(()->{try{MessageService m=new MessageService();FutureLetterService f=new FutureLetterService();if(m.count()==0){m.release("I hope you know that your quiet kindness mattered more than you could see.","Unspoken Words");m.release("Somewhere, someone is learning to be proud of the life they made it through.","Secret Thoughts");m.release("Dear future me: I hope you still make time to look at the moon.","Random Thoughts");}BottleService b=new BottleService(m);new UserInterface(m,b,f,new StatisticsService(m,f)).show();}catch(Exception e){JOptionPane.showMessageDialog(null,"The ocean could not open: "+e.getMessage(),"Startup error",JOptionPane.ERROR_MESSAGE);}});}}
